import{chromium}from'playwright-core';const b=await chromium.connectOverCDP('http://127.0.0.1:9224');try{const p=b.contexts().flatMap(x=>x.pages()).find(p=>p.url()==='http://127.0.0.1:30000/game');const z=await p.evaluate(()=>{if(!game.user.isGM||game.users.activeGM.id!==game.user.id)throw Error('No GM');const scene=game.scenes.get('CAVSG01Scene0001');return {studio:Array.from(game.scenes).filter(s=>/art studio|dahlia|H-G07|H-G08|studio/i.test(s.name)).map(s=>({name:s.name,id:s.id,regions:Array.from(s.regions).map(r=>({id:r.id,name:r.name,behaviors:r.behaviors.size}))})),grove:{width:scene.width,height:scene.height,background:scene.background.src,regions:Array.from(scene.regions).map(r=>({id:r.id,name:r.name,shapes:r.toObject().shapes,behaviors:Array.from(r.behaviors).map(b=>({id:b.id,type:b.type,disabled:b.disabled}))}))}}});console.log(JSON.stringify(z))}finally{await b.close()}